Why This Is Asked
- Tests dynamic augmentation of a trie with aggregated metrics and tie-breaking logic.

Key Concepts
- Trie augmentation with subtreeSum and subtreeBest; O(length) updates; O(length) queries.
- Correct handling of weight deltas, insertions, and removals; lexicographic tiebreaks.

Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.subtreeSum = 0;
    this.bestWord = null;
    this.bestWeight = 0;
  }
}
class DynamicDict {
  constructor() {
    this.root = new TrieNode();
    this.wordWeights = new Map();
  }
  add(word, delta) {
    let node = this.root;
    const newWeight = (this.wordWeights.get(word) || 0) + delta;
    this.wordWeights.set(word, newWeight);
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
      node.subtreeSum += delta;
      if (newWeight > node.bestWeight || 
          (newWeight === node.bestWeight && word < node.bestWord)) {
        node.bestWord = word;
        node.bestWeight = newWeight;
      }
    }
  }
  query(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.children.has(char)) {
        return [0, null];
      }
      node = node.children.get(char);
    }
    return [node.subtreeSum, node.bestWord];
  }
}
```

Complexity Analysis
- `add(word, delta)`: O(|word|) time, O(1) extra space per character
- `query(prefix)`: O(|prefix|) time, O(1) extra space

Edge Cases
- Negative deltas potentially removing words completely
- Multiple words with equal maximum weights requiring lexicographic tie-breaking
- Empty queries and non-existent prefixes
- Words sharing common prefixes affecting aggregate calculations

## Why This Is Asked

Tests algorithmic depth and practical handling of worst-case quicksort behavior.

## Key Concepts

- Introsort: hybrid of quicksort and heapsort with depth guard
- Median-of-three pivot to avoid pathological inputs
- In-place partition and recursion depth management
- Complexity: O(n log n) average and worst-case; O(log n) stack space

## Code Example

```javascript
// Introsort skeleton in JS
function introsort(arr) {
  const n = arr.length;
  if (n <= 1) return;
  const maxDepth = Math.floor(2 * Math.log2(n));
  function swap(i, j) { const t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
  function medianOfThree(lo, mid, hi) {
    if (arr[lo] > arr[mid]) swap(lo, mid);
    if (arr[lo] > arr[hi]) swap(lo, hi);
    if (arr[mid] > arr[hi]) swap(mid, hi);
    return mid;
  }
  function partition(lo, hi) {
    const mid = Math.floor((lo + hi) / 2);
    const m = medianOfThree(lo, mid, hi);
    swap(m, hi);
    const pivot = arr[hi];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (arr[j] <= pivot) { swap(i, j); i++; }
    }
    swap(i, hi);
    return i;
  }
  function heapSort(lo, hi) {
    const n = hi - lo + 1;
    function heapify(i, size) {
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        let largest = i;
        if (l < size && arr[lo + l] > arr[lo + largest]) largest = l;
        if (r < size && arr[lo + r] > arr[lo + largest]) largest = r;
        if (largest !== i) { swap(lo + i, lo + largest); i = largest; } else break;
      }
    }
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) heapify(i, n);
    for (let end = n - 1; end > 0; end--) {
      swap(lo, lo + end);
      heapify(0, end);
    }
  }
  function insertionSort(lo, hi) {
    for (let i = lo + 1; i <= hi; i++) {
      const key = arr[i];
      let j = i - 1;
      while (j >= lo && arr[j] > key) { arr[j + 1] = arr[j]; j--; }
      arr[j + 1] = key;
    }
  }
  function quickSort(lo, hi, depth) {
    const size = hi - lo + 1;
    if (size <= 16) { insertionSort(lo, hi); return; }
    if (depth <= 0) { heapSort(lo, hi); return; }
    const p = partition(lo, hi);
    quickSort(lo, p - 1, depth - 1);
    quickSort(p + 1, hi, depth - 1);
  }
  quickSort(0, n - 1, maxDepth);
}
```

## Follow-up Questions
- How would you adapt this to sort objects by a numeric key while preserving comparator locality?
- Compare cache behavior of introsort vs pure mergesort on large datasets.

## Why This Is Asked

The problem mirrors real-world build systems and DAG validations, requiring both cycle detection and a valid execution order.

## Key Concepts

- DFS with 3-color marking to detect cycles
- Topological sort via postorder push
- Handling multiple components in a possibly disconnected graph

## Code Example

```javascript
function dfsTopo(graph) {
  const n = graph.length;
  const color = Array(n).fill(0); // 0 white, 1 gray, 2 black
  const order = [];
  const cycles = [];
  function dfs(u) {
    color[u] = 1;
    for (const v of graph[u] || []) {
      if (color[v] === 0) {
        if (dfs(v)) return true;
      } else if (color[v] === 1) {
        cycles.push([u, v]);
        return true;
      }
    }
    color[u] = 2;
    order.push(u);
    return false;
  }
  for (let i = 0; i < n; i++) {
    if (color[i] === 0) {
      if (dfs(i)) break;
    }
  }
  return { topo: order.reverse(), cycle: cycles.length ? cycles : null };
}
```

