## Why This Question Is Asked
This question tests dynamic programming intuition on a constrained path counting problem with simple transitions and boundary conditions.

## Key Concepts
- **Recurrence relation:** f(i) = f(i+1) + f(i+2) with modulo arithmetic
- **Memoization vs. tabulation:** Trade-offs between recursive top-down with caching versus iterative bottom-up approaches
- **Edge conditions:** Blocked start/end positions, single-cell arrays

## Code Example
```javascript
function countPaths(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  // Memoized DFS
  const memo = Array(n).fill(-1);
  function dfs(i) {
    if (i === n - 1) return blocked[i] ? 0 : 1;
    if (i >= n || blocked[i]) return 0;
    if (memo[i] !== -1) return memo[i];
    memo[i] = (dfs(i + 1) + dfs(i + 2)) % MOD;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up DP (O(1) space)
function countPathsDP(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  let next2 = 1, next1 = blocked[n - 1] ? 0 : 1;
  for (let i = n - 2; i >= 0; i--) {
    const curr = blocked[i] ? 0 : (next1 + next2) % MOD;
    next2 = next1;
    next1 = curr;
  }
  return next1;
}
```

## Why This Is Asked
Tests DP with dual objectives: minimize cost and count optimal deletion sets, plus implement in two styles. It also covers edge cases like empty substrings and ties.

## Key Concepts
- DP on substrings; store (cost, ways).
- Memoization and bottom-up parallels; careful counting on ties.
- Modulo arithmetic for counts.

## Code Example
```javascript
// Memoized DFS
function solveMemo(s, delCost){
  const n = s.length;
  const memoCost = Array.from({length:n},()=>Array(n).fill(-1));
  const memoWays = Array.from({length:n},()=>Array(n).fill(0));
  const MOD = 1_000_000_007;
  function dfs(l,r){
    if (l>=r) return {cost:0, ways:1};
    if (memoCost[l][r]!==-1) return {cost:memoCost[l][r], ways:memoWays[l][r]};
    if (s[l]===s[r]){
      const res = dfs(l+1,r-1);
      memoCost[l][r]=res.cost;
      memoWays[l][r]=res.ways;
      return res;
    } else {
      const A = dfs(l+1,r);
      const B = dfs(l,r-1);
      let cost;
      let ways = 0;
      if (A.cost + delCost[l] < B.cost + delCost[r]){
        cost = A.cost + delCost[l];
        ways = A.ways;
      } else if (B.cost + delCost[r] < A.cost + delCost[l]){
        cost = B.cost + delCost[r];
        ways = B.ways;
      } else {
        cost = A.cost + Math.min(delCost[l], delCost[r]);
        ways = (A.ways + B.ways) % MOD;
      }
      memoCost[l][r]=cost; memoWays[l][r]=ways;
      return {cost, ways};
    }
  }
  return dfs(0,n-1);
}
```

