function sortInPlace(arr){
  const TH = 16;
  const swap=(a,i,j)=>{const t=a[i]; a[i]=a[j]; a[j]=t;};
  const medianOfThree=(a,i,j,k)=>{let x=[a[i],i],[a[j],j],[a[k],k].sort((p,q)=>p[0]-q[0]); return a[x[1]];};
  // iterative 3-way quicksort skeleton
  const stack=[[0,arr.length-1]];
  while(stack.length){
    const [lo,hi]=stack.pop();
    if(hi-lo+1<=TH){ // insertion sort for small partitions
      for(let i=lo+1;i<=hi;i++){
        let t=arr[i], j=i-1;
        while(j>=lo && arr[j]>t){ arr[j+1]=arr[j]; j-- }
        arr[j+1]=t;
      }
      continue;
    }
    // median-of-three pivot
    const mid=(lo+hi)>>1;
    const pivot= medianOfThree(arr, lo, mid, hi);
    // 3-way partition
    let lt=lo, i=lo, gt=hi;
    while(i<=gt){
      if(arr[i]<pivot) swap(arr, lt++, i++);
      else if(arr[i]>pivot) swap(arr, i, gt--);
      else i++;
    }
    stack.push([lo, lt-1]);
    stack.push([gt+1, hi]);
  }
}
```

## Why This Is Asked

Tests ability to model DP with obstacles and variable step sizes, requiring careful base cases and transition logic. It also assesses both memoization and tabulation familiarity.

## Key Concepts

- DP with multiple transitions (1..k)
- Handling blocked steps
- Memoization vs tabulation
- Time complexity: O(n*maxJump); Space: O(n) (or O(maxJump) with optimization)

## Code Example

```javascript
// Bottom-up tabulation
function countWays(n, maxJump, blocked) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  for (let i = 1; i <= n; i++) {
    if (blocked[i]) { dp[i] = 0; continue; }
    for (let j = 1; j <= maxJump; j++) {
      if (i - j >= 0) dp[i] += dp[i - j];
    }
  }
  return dp[n];
}
```

```javascript
// Memoized recursive version
function countWaysRec(n, maxJump, blocked, i = n, memo = {}) {
  if (i === 0) return 1;
  if (i < 0 || blocked[i]) return 0;
  if (memo[i] !== undefined) return memo[i];
  let ways = 0;
  for (let t = 1; t <= maxJump; t++) ways += countWaysRec(n, maxJump, blocked, i - t, memo);
  memo[i] = ways;
  return ways;
}
```

